/// <summary>
/// Find by reference
/// </summary>
/// <param name = "_reqItemTableRecID">_reqItemTableRecID</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>ReqItemTable</returns>
public static METReqItemTable find(RefRecId _reqItemTableRecID, boolean _forUpdate = false)
{
    METReqItemTable metReqItemTable;
    if(_reqItemTableRecID)
    {
        metReqItemTable.selectForUpdate(_forUpdate);
        select firstonly metReqItemTable
           where   metReqItemTable.RefRecId == _reqItemTableRecID;
    }
    return metReqItemTable;
}

    /// <summary>
    /// Populate slot area
    /// </summary>
    public void populateSlotArea()
    {
        ReqItemTable reqItemTable;
        InventDim inventDim;
        METSlotTable metSlotTable;
        METSlotLocationType metSlotLocationType;
        Set slotTypeSet = new Set(Types::Enum);
        METSlotArea metSlotArea;

        while select Type from metSlotTable
            join InventLocationId from inventDim
            where metSlotTable.InventLocationId == inventDim.InventLocationId
            exists join reqItemTable
            where reqItemTable.CovInventDimId == inventDim.inventDimId
            && reqItemTable.RecId == this.RefRecId
        {
            metSlotLocationType = metSlotTable.Type;

            if (!slotTypeSet.in(metSlotLocationType))
            {
                if (metSlotTable)
                {
                    metSlotArea = this.searchSlotArea(metSlotLocationType, inventDim.InventLocationId);
                    if (metSlotArea)
                    {
                        this.SlotArea = metSlotArea;
                        break;
                    }
                    slotTypeSet.add(metSlotLocationType);
                }
            }
        }
    }

    /// <summary>
    /// Search slot area
    /// </summary>
    /// <param name = "metSlotLocationType">METSlotLocationType</param>
    /// <param name = "_inventLocationId">InventLocationIds</param>
    /// <returns>METSlotArea</returns>
    public METSlotArea searchSlotArea(METSlotLocationType metSlotLocationType, InventLocationId _inventLocationId)
    {
        METSlotTableView metSlotTableView;
        METSlotLoc1Area metSlotLoc1Area;

        if (_inventLocationId && metSlotLocationType == METSlotLocationType::Type1)
        {
            metSlotLoc1Area = strReplace(this.SlotLoc1Area, "-", "");
            metSlotLoc1Area = subStr(metSlotLoc1Area, 1, 3);

            select firstonly Area from metSlotTableView
                order by FromSlotSubString desc
                where metSlotTableView.FromSlotSubString <= metSlotLoc1Area
                && metSlotTableView.ToSlotSubString >= metSlotLoc1Area
                && metSlotTableView.Type == enum2int(metSlotLocationType)
                && metSlotTableView.InventLocationId == _inventLocationId;

            if (metSlotTableView && (this.SlotArea != metSlotTableView.Area))
            {
                return metSlotTableView.Area;
            }
        }
        else if (_inventLocationId && (metSlotLocationType == METSlotLocationType::Type2 || metSlotLocationType == METSlotLocationType::Type3 || metSlotLocationType == METSlotLocationType::Type4 || metSlotLocationType == METSlotLocationType::Type5))
        {
            metSlotLoc1Area = strReplace(this.SlotLoc1Area, "-", "");
            metSlotLoc1Area = subStr(metSlotLoc1Area, 1, 2);

            select firstonly Area from metSlotTableView
                order by FromSlotSubString desc
                where metSlotTableView.FromSlotSubString <= metSlotLoc1Area
                && metSlotTableView.ToSlotSubString >= metSlotLoc1Area
                && metSlotTableView.Type == enum2int(metSlotLocationType)
                && metSlotTableView.InventLocationId == _inventLocationId;

            if (metSlotTableView && (this.SlotArea != metSlotTableView.Area))
            {
                return metSlotTableView.Area;
            }         
        } 
       
        return '';
    }

    /// <summary>
    /// Select and populate slot location
    /// </summary>
    public void selectAndPopulateSlotLocationToTransferSites()
    {
        ReqItemTable reqItemTable;
        InventLocation inventLocation;

        select firstonly reqItemTable
            where reqItemTable.RecId == this.RefRecId;

        inventLocation = InventLocation::find(InventDim::find(reqItemTable.CovInventDimId).InventLocationId);

        if(METIGAWarehouses::exist(inventLocation.InventLocationId)) // Check if warehouse is IGA warehouse
        {
            if(inventLocation.METNDCWarehouse) // Check if warehouse is NDC
            {
                inventLocation.clear();
                while select inventLocation
                    where inventLocation.METNDCWarehouse == NoYes::Yes
                {
                    this.populateSlotLocationToTransferSites(reqItemTable, inventLocation);
                }
            }
            else // Non NDC warehouse
            {
                this.populateSlotLocationToTransferSites(reqItemTable, inventLocation);
            }
        }
    }

    /// <summary>
    /// Populate slot location to transfer sites 
    /// </summary>
    /// <param name = "_reqItemTable">ReqItemTable</param>
    /// <param name = "_inventLocation">InventLocation</param>
    private void populateSlotLocationToTransferSites(ReqItemTable _reqItemTable, InventLocation _inventLocation)
    {
        ReqItemTable reqItemTableLocal;
        METReqItemTable metReqItemTable;
        InventDim inventDimLocal;
        InventLocation inventLocationLocal;

        while select metReqItemTable
            exists join reqItemTableLocal
            where reqItemTableLocal.RecId == metReqItemTable.RefRecId
            && reqItemTableLocal.ItemId == _reqItemTable.ItemId
            && reqItemTableLocal.ReqPOType == ReqPOType::Transfer
            && reqItemTableLocal.InventLocationIdReqMain == _inventLocation.InventLocationId
            exists join inventDimLocal
            where inventDimLocal.inventDimId == reqItemTableLocal.CovInventDimId
            exists join inventLocationLocal
            where inventLocationLocal.InventLocationId == inventDimLocal.InventLocationId
            && inventLocationLocal.METCSDWarehouse == NoYes::Yes
        {
            metReqItemTable.selectForUpdate(true);
            metReqItemTable.SlotLoc1Area = this.SlotLoc1Area;
            metReqItemTable.populateSlotArea();
            metReqItemTable.update();
        }


    }

/// <summary>
/// Check for alphabet
/// </summary>
/// <param name = "ch">Str</param>
/// <returns>boolean</returns>
private static boolean isAlpha(str ch)
{
    System.String netStr = ch;
    return System.Char::IsLetter(netStr.get_Chars(0));
}

    /// <summary>
    /// Modified field
    /// </summary>
    /// <param name = "_fieldId">FieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        METReqItemTable   this_Orig = this.orig();

        super(_fieldId);

        switch (_fieldId)
        {
            case fieldNum(METReqItemTable, SlotLoc1Area) :
                if(this_Orig.SlotLoc1Area != this.SlotLoc1Area)
                {
                    ttsbegin;
                    // Populate Slot area
                    this.populateSlotArea();
                
                    // Update slot Location 1 to transfer sites
                    this.selectAndPopulateSlotLocationToTransferSites();
                    ttscommit;                 
                    
                }
        }
        
    }
